const nav=document.querySelector("#panel-nav");nav.addEventListener("click",event=>{const button=event.target.closest("[data-tab]");if(!button)return;for(const tab of nav.querySelectorAll("[data-tab]"))tab.setAttribute("aria-pressed",String(tab===button));for(const panel of document.querySelectorAll("[data-panel]"))panel.hidden=panel.dataset.panel!==button.dataset.tab;window.dispatchEvent(new Event("resize"));window.scrollTo({top:0,behavior:"smooth"})});
